	private static void awaitCloseEntered(Thread closer) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
		while (System.nanoTime() < deadline) {
			for (StackTraceElement frame : closer.getStackTrace()) {
				if (frame.getClassName().equals(LmdbSailStore.class.getName())
						&& frame.getMethodName().equals("close")) {
					return;
				}
			}
			if (!closer.isAlive()) {
				throw new AssertionError("close exited before the held save drained");
			}
			Thread.yield();
		}
		throw new AssertionError("close never reached the backing owner: "
				+ java.util.Arrays.toString(closer.getStackTrace()));
	}

