	/** Hit proof: the worker has either published or reached its attempted conservative withdrawal. */
	private static void awaitQualificationOrWithdrawal(Fixture fixture) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
		while (System.nanoTime() < deadline) {
			if (fixture.completion.isDone()) {
				return;
			}
			Thread worker = fixture.files.gatedWriter;
			if (worker != null) {
				boolean saving = false;
				boolean withdrawing = false;
				for (StackTraceElement frame : worker.getStackTrace()) {
					saving |= frame.getClassName().equals(StoreProperties.class.getName())
							&& frame.getMethodName().equals("save");
					withdrawing |= frame.getClassName().equals(TripleStore.class.getName())
							&& frame.getMethodName().equals("abandonDeferredRdfTermDomainPublication");
				}
				if (saving && withdrawing) {
					return;
				}
			}
			Thread.yield();
		}
		throw new AssertionError("post-ready worker did not reach qualification or conservative withdrawal");
	}

	@Test
	void shutdownWinningDuringFinalCleanupAbandonsWithoutHoldingNativeLocks(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		long predicateId = seedUnqualifiedStore(directory);
		GateFileOps files = new GateFileOps();
		files.guardNativeClose.set(true);
		files.guardFinalPublication.set(true);
		files.failFinalPublication.set(false);
		files.holdFinalThroughInterrupt.set(true);
		files.guardWithdrawal.set(true);
		try (Fixture fixture = Fixture.open(directory, files)) {
			fixture.start();
			try {
				fixture.awaitForcedProfileSave();
				files.release.countDown();
				assertTrue(files.finalPublicationEntered.await(30, TimeUnit.SECONDS));
				fixture.externalClose = new FutureTask<>(() -> {
					fixture.backing.close();
					return null;
				});
				Thread closer = Thread.ofPlatform()
						.daemon()
						.name("domain-close-wins-test")
						.unstarted(fixture.externalClose);
				closer.start();
				assertTrue(files.finalPublicationInterrupted.await(30, TimeUnit.SECONDS),
						"shutdown must interrupt the actual final-publication worker");
				awaitShutdownDrainingPostReady(closer);
				assertFalse(fixture.externalClose.isDone(), "shutdown owns the close boundary while draining");
				files.finalPublicationRelease.countDown();
				CompletableFuture.anyOf(files.withdrawalEntered, fixture.completion.handle((result, failure) -> null))
						.get(30, TimeUnit.SECONDS);
				if (!files.withdrawalEntered.isDone()) {
					try {
						fixture.completion.get(1, TimeUnit.SECONDS);
					} catch (ExecutionException failedBeforeWithdrawal) {
						throw new AssertionError("post-ready maintenance failed before the withdrawal gate",
								failedBeforeWithdrawal.getCause());
					}
				}
				assertTrue(files.withdrawalEntered.isDone(), "the prepared publication must reach withdrawal");
				assertFalse(fixture.externalClose.isDone(), "shutdown must wait for the withdrawal save");
				assertTrue(fixture.directoryLock.isActive());
				assertFalse(fixture.backing.getTripleStore().closedForDomainQualification());
				assertFalse(fixture.backing.valueStore().closedForDomainQualification());
				assertFalse(files.unsafeClose.get());
				var info = java.lang.management.ManagementFactory.getThreadMXBean()
						.getThreadInfo(
								new long[] { files.gatedWriter.threadId() }, true, true)[0];
				assertNotNull(info, "the post-ready owner remains live during the save");
				for (var held : info.getLockedSynchronizers()) {
					assertFalse(held.getClassName().startsWith("java.util.concurrent.locks.ReentrantLock$"),
							"the withdrawing worker must not hold close, sink or publication locks: " + held);
				}
				var triplesBarrier = fixture.backing.getTripleStore().getTxnManager().lockManager();
				long triplesStamp = triplesBarrier.tryWriteLock();
				assertNotEquals(0L, triplesStamp, "withdrawal must not hold the triple native barrier");
				triplesBarrier.unlockWrite(triplesStamp);
				var valuesBarrier = fixture.backing.valueStore().getTxnManager().lockManager();
				long valuesStamp = valuesBarrier.tryWriteLock();
				assertNotEquals(0L, valuesStamp, "withdrawal must not hold the dictionary native barrier");
				valuesBarrier.unlockWrite(valuesStamp);
			} finally {
				files.release.countDown();
				files.finalPublicationRelease.countDown();
				files.withdrawalRelease.countDown();
			}
			try {
				fixture.completion.get(30, TimeUnit.SECONDS);
				assertNull(files.withdrawalFailure.get());
			} catch (ExecutionException failure) {
				IOException interruptedSave = files.withdrawalFailure.get();
				assertInstanceOf(java.nio.channels.ClosedByInterruptException.class, interruptedSave);
				assertInstanceOf(IllegalStateException.class, failure.getCause());
				assertSame(interruptedSave, failure.getCause().getCause(),
						"a real interrupted save failure must remain observable");
			}
			fixture.externalClose.get(30, TimeUnit.SECONDS);
			assertFalse(files.unsafeClose.get());
		}
		assertReopen(directory, predicateId);
	}

	private static void awaitShutdownDrainingPostReady(Thread closer) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(20);
		while (System.nanoTime() < deadline) {
			for (StackTraceElement frame : closer.getStackTrace()) {
				if (frame.getClassName().equals(LmdbSailStore.class.getName())
						&& frame.getMethodName().equals("awaitPostReadyInitializationForShutdown")) {
					return;
				}
			}
			if (!closer.isAlive()) {
				throw new AssertionError("shutdown returned before reaching its post-ready drain");
			}
			Thread.yield();
		}
		throw new AssertionError("shutdown did not reach its post-ready drain: "
				+ java.util.Arrays.toString(closer.getStackTrace()));
	}

	@Test
	void memoryOnlyPropertiesStillPermitValidatedPairedDomains(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		StoreProperties properties = new StoreProperties();
		try (LmdbSailStore backing = new LmdbSailStore(directory.toFile(), properties, config(), false)) {
			backing.startBackgroundMaintenanceAfterInitialization();
			backing.awaitPostReadyInitialization(30, TimeUnit.SECONDS);
			try (var source = backing.getExplicitSailSource();
					var sink = source.sink(IsolationLevels.READ_COMMITTED)) {
				sink.approve(S, P, O, null);
				sink.flush();
			}
			long predicateId = ((ValueStore) backing.getValueFactory()).getId(P);
			assertRows(backing);
			assertEquals(RdfTermDomain.IRI, pairedDomain(backing, predicateId).orElseThrow());
			assertTrue(Files.notExists(directory.resolve(StoreProperties.FILE_NAME)),
					"this control does not claim persistent profile authority");
		}
	}

