	@Test
	void queuedDictionaryMaintenanceSettlesBeforeSingleDomainCommit(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		long predicateId = seedUnqualifiedStore(directory);
		GateFileOps files = new GateFileOps();
		files.guardNativeClose.set(true);
		files.guardFinalPublication.set(true);
		files.failFinalPublication.set(false);
		try (Fixture fixture = Fixture.open(directory, files)) {
			ValueStore values = fixture.backing.valueStore();
			long before = values.lastTransactionId();
			values.requestTermIndexRebuild("spoc,cspo,psoc");
			assertEquals("QUEUED", values.indexRebuildStatus());
			long settled = fixture.drainIndependentIndexMaintenance();
			assertTrue(settled > before, "the real queued index work must commit before domain maintenance");
			assertEquals("IDLE", values.indexRebuildStatus());
			fixture.start();
			try {
				fixture.awaitForcedProfileSave();
				assertEquals(settled, values.lastTransactionId(),
						"the dictionary generation remains stable throughout the initial domain rebuild");
				assertEquals(1, files.deferredDomainCommits.get(), "the initial domain rebuild commits exactly once");
			} finally {
				files.release.countDown();
				files.finalPublicationRelease.countDown();
			}
			fixture.completion.get(30, TimeUnit.SECONDS);
			assertRows(fixture.backing);
			assertEquals(RdfTermDomain.IRI, pairedDomain(fixture.backing, predicateId).orElseThrow());
		}
	}

	@Test
	void writerCommittedDuringFinalCleanupCannotPublishAnOlderDomain(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		long predicateId = seedUnqualifiedStore(directory);
		var literal = VF.createLiteral("a later literal that remains in the dictionary");
		IRI laterSubject = VF.createIRI("urn:domain-save:later-subject");
		GateFileOps files = new GateFileOps();
		files.guardNativeClose.set(true);
		files.guardFinalPublication.set(true);
		files.failFinalPublication.set(false);
		try (Fixture fixture = Fixture.open(directory, files)) {
			long dictionaryGeneration = fixture.drainIndependentIndexMaintenance();
			fixture.start();
			try {
				fixture.awaitForcedProfileSave();
				assertEquals(dictionaryGeneration, fixture.backing.valueStore().lastTransactionId(),
						"the initial rebuild must not overlap an independent dictionary commit");
				assertEquals(1, files.deferredDomainCommits.get(),
						"the initial full rebuild must have completed a native commit");
				files.release.countDown();
				assertTrue(files.finalPublicationEntered.await(30, TimeUnit.SECONDS),
						"the post-ready owner must reach final publication cleanup");
				var write = fixture.workers.submit(() -> {
					long before = fixture.backing.getTripleStore().lastTransactionId();
					try (var source = fixture.backing.getExplicitSailSource();
							var sink = source.sink(IsolationLevels.READ_COMMITTED)) {
						sink.approve(laterSubject, P, literal, null);
						sink.flush();
					}
					long after = fixture.backing.getTripleStore().lastTransactionId();
					assertTrue(after > before, "the later writer must commit a new native generation");
					return after;
				});
				long committed = write.get(30, TimeUnit.SECONDS);
				assertTrue(fixture.backing.getTripleStore().lastTransactionId() >= committed);
				assertFalse(fixture.completion.isDone(), "the earlier publication remains held");
				fixture.workers.submit(() -> assertObjects(fixture.backing, literal)).get(15, TimeUnit.SECONDS);
			} finally {
				files.release.countDown();
				files.finalPublicationRelease.countDown();
			}
			fixture.completion.get(30, TimeUnit.SECONDS);
			RdfTermDomain domain = fixture.workers.submit(() -> {
				assertObjects(fixture.backing, literal);
				return pairedDomain(fixture.backing, predicateId).orElseThrow();
			}).get(15, TimeUnit.SECONDS);
			assertTrue(domain.has(RdfTermDomain.Fact.IRI), "the current domain must allow the original IRI");
			assertTrue(domain.has(RdfTermDomain.Fact.LITERAL), "the current domain must allow the committed literal");
		}
	}

	@Test
	void interveningWriterDoesNotRebuildLoadedDomainWhenAutomaticRebuildIsDisabled(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		LmdbStoreConfig settings = config().setPredicateGuaranteeIndexAutoRebuild(false);
		var literal = VF.createLiteral("the remaining literal");
		IRI retainedOwner = VF.createIRI("urn:domain-save:retained-owner");
		IRI unrelated = VF.createIRI("urn:domain-save:unrelated-predicate");
		RdfTermDomain mixed = RdfTermDomain.classify(O).combine(RdfTermDomain.classify(literal));
		LmdbStore seed = new LmdbStore(directory.toFile(), settings);
		SailRepository repository = new SailRepository(seed);
		long predicateId;
		try (AutoCloseable ignored = repository::shutDown) {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(seed, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(S, P, O);
				connection.add(S, P, literal);
				connection.add(S, retainedOwner, O);
				connection.commit();
				connection.begin();
				connection.remove(S, P, O);
				connection.commit();
			}
			predicateId = ((ValueStore) seed.getBackingStore().getValueFactory()).getId(P);
			assertEquals(mixed, pairedDomain(seed.getBackingStore(), predicateId).orElseThrow(),
					"the disabled rebuild retains the original conservative domain");
			assertOnlyPredicateValue(seed.getBackingStore(), P, literal);
		}
		StoreProperties preflight = new StoreProperties(directory.toFile());
		assertTrue(preflight.load());
		assertNotNull(PreparedBulkStore.read(directory, preflight, settings),
				"the existing store must have a prepared no-work generation");
		assertTrue(preflight.rdfTermDomainQualifiedAtOpen,
				"the existing conservative domain must have a valid paired qualification");
		assertEquals(TripleStore.RdfTermDomainStartup.LOAD,
				TripleStore.rdfTermDomainStartup(preflight, true, false, false, java.util.Set.of()),
				"the qualified store must select the no-write LOAD startup path");

		GateFileOps files = new GateFileOps();
		files.guardFinalPublication.set(true);
		files.failFinalPublication.set(false);
		try (Fixture fixture = Fixture.open(directory, files, settings)) {
			assertTrue(fixture.backing.getTripleStore().hasDeferredRdfTermDomainStartup(),
					"the actual owner must have a deferred domain operation");
			assertEquals(TripleStore.RdfTermDomainStartup.LOAD,
					TripleStore.rdfTermDomainStartup(fixture.properties, true, false, false, java.util.Set.of()),
					"the actual owner must begin from qualified LOAD authority");
			long before = fixture.backing.getTripleStore().lastTransactionId();
			fixture.start();
			try {
				fixture.awaitForcedProfileSave();
				assertEquals(before, fixture.backing.getTripleStore().lastTransactionId(),
						"loading existing domain metadata must not commit a triple transaction");
				files.release.countDown();
				assertTrue(files.finalPublicationEntered.await(30, TimeUnit.SECONDS),
						"the LOAD publication must reach its final cleanup after validation");
				long committed = fixture.workers.submit(() -> {
					try (var source = fixture.backing.getExplicitSailSource();
							var sink = source.sink(IsolationLevels.READ_COMMITTED)) {
						sink.approve(S, unrelated, literal, null);
						sink.flush();
					}
					return fixture.backing.getTripleStore().lastTransactionId();
				}).get(30, TimeUnit.SECONDS);
				assertTrue(committed > before, "the ordinary writer must commit a later triple generation");
				assertFalse(fixture.completion.isDone(), "the earlier publication remains gated");
				fixture.workers.submit(() -> {
					assertOnlyPredicateValue(fixture.backing, P, literal);
					assertOnlyPredicateValue(fixture.backing, unrelated, literal);
				}).get(15, TimeUnit.SECONDS);
			} finally {
				files.release.countDown();
				files.finalPublicationRelease.countDown();
			}
			fixture.completion.get(30, TimeUnit.SECONDS);
			assertOnlyPredicateValue(fixture.backing, P, literal);
			assertOnlyPredicateValue(fixture.backing, unrelated, literal);
			assertEquals(mixed, pairedDomain(fixture.backing, predicateId).orElseThrow(),
					"a stale LOAD must not trigger a full rebuild when automatic rebuild is disabled");
		}

		LmdbStore reopened = new LmdbStore(directory.toFile(), settings);
		try (AutoCloseable ignored = reopened::shutDown) {
			reopened.init();
			LmdbTestUtil.awaitPostReadyInitialization(reopened, 30, TimeUnit.SECONDS);
			assertOnlyPredicateValue(reopened.getBackingStore(), P, literal);
			assertOnlyPredicateValue(reopened.getBackingStore(), unrelated, literal);
			assertEquals(mixed, pairedDomain(reopened.getBackingStore(), predicateId).orElseThrow(),
					"the conservative domain must survive cold reopen");
		}
	}

	@Test
	void interveningWriterDoesNotTurnUnmarkedRetryIntoFullRebuild(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		LmdbStoreConfig settings = config();
		var literal = VF.createLiteral("an original literal");
		var later = VF.createBNode("domain-save-later-node");
		RdfTermDomain initial = RdfTermDomain.classify(O).combine(RdfTermDomain.classify(literal));
		RdfTermDomain updated = initial.combine(RdfTermDomain.classify(later));
		LmdbStore seed = new LmdbStore(directory.toFile(), settings);
		SailRepository repository = new SailRepository(seed);
		long predicateId;
		try (AutoCloseable ignored = repository::shutDown) {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(seed, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(S, P, O);
				connection.add(S, P, literal);
				connection.commit();
			}
			predicateId = ((ValueStore) seed.getBackingStore().getValueFactory()).getId(P);
			assertEquals(initial, pairedDomain(seed.getBackingStore(), predicateId).orElseThrow());
			assertPredicateValues(seed.getBackingStore(), java.util.Set.of(O, literal));
		}
		StoreProperties preflight = new StoreProperties(directory.toFile());
		assertTrue(preflight.load());
		assertNotNull(PreparedBulkStore.read(directory, preflight, settings));
		assertTrue(preflight.rdfTermDomainQualifiedAtOpen);
		assertNotNull(preflight.getRdfTermDomainQualification(),
				"the earlier readable state has a durable qualification");
		assertEquals(TripleStore.RdfTermDomainStartup.REBUILD_MARKED,
				TripleStore.rdfTermDomainStartup(preflight, true, true, false, java.util.Set.of()));

		GateFileOps files = new GateFileOps();
		files.guardNativeClose.set(true);
		files.guardFinalPublication.set(true);
		files.guardRetryScan.set(true);
		files.failFinalPublication.set(false);
		try (Fixture fixture = Fixture.open(directory, files, settings)) {
			try (LmdbSailStore.DatasetAdmission admission = fixture.backing.beginDatasetAdmission(
					IsolationLevels.SNAPSHOT_READ, null)) {
				LmdbSailStore.ReadView view = admission.view();
				view.requireDictionaryTermSnapshot();
				TripleStore.DeferredRdfTermDomainPlan plan = fixture.backing.getTripleStore()
						.scanDeferredRdfTermDomains(view.tripleTxn(), view.valueSnapshot());
				assertEquals(TripleStore.RdfTermDomainStartup.REBUILD_MARKED, plan.startup());
				assertFalse(plan.needsWrite(), "the actual paired scan has no marked work");
			}
			long before = fixture.backing.getTripleStore().lastTransactionId();
			fixture.start();
			try {
				fixture.awaitForcedProfileSave();
				assertEquals(before, fixture.backing.getTripleStore().lastTransactionId(),
						"the first unmarked attempt must not write a triple transaction");
				assertEquals(0, files.deferredDomainCommits.get());
				files.release.countDown();
				assertTrue(files.finalPublicationEntered.await(30, TimeUnit.SECONDS));
				long committed = fixture.workers.submit(() -> {
					try (var source = fixture.backing.getExplicitSailSource();
							var sink = source.sink(IsolationLevels.READ_COMMITTED)) {
						sink.approve(S, P, later, null);
						sink.flush();
					}
					return fixture.backing.getTripleStore().lastTransactionId();
				}).get(30, TimeUnit.SECONDS);
				assertTrue(committed > before, "the same-predicate writer must commit");
				assertFalse(fixture.completion.isDone());
				fixture.workers
						.submit(() -> assertPredicateValues(fixture.backing, java.util.Set.of(O, literal, later)))
						.get(15, TimeUnit.SECONDS);
			} finally {
				files.release.countDown();
				files.finalPublicationRelease.countDown();
			}
			try {
				assertTrue(files.retryScanEntered.await(30, TimeUnit.SECONDS),
						"the post-ready owner must enter the fresh paired retry scan");
				assertFalse(fixture.completion.isDone());
				fixture.workers.submit(() -> {
					assertPredicateValues(fixture.backing, java.util.Set.of(O, literal, later));
					assertTrue(pairedDomain(fixture.backing, predicateId).isEmpty(),
							"the formerly readable domain must remain unavailable while retry is held");
					assertFalse(fixture.backing.getTripleStore().mayQualifyRdfTermDomainsAfterClose(),
							"the raw readable flag must not authorize a close candidate");
					return null;
				}).get(15, TimeUnit.SECONDS);
			} finally {
				files.retryScanRelease.countDown();
			}
			fixture.completion.get(30, TimeUnit.SECONDS);
			assertPredicateValues(fixture.backing, java.util.Set.of(O, literal, later));
			assertEquals(updated, pairedDomain(fixture.backing, predicateId).orElseThrow());
			assertEquals(0, files.deferredDomainCommits.get(),
					"retrying unmarked work must not commit a full domain replacement");
		}
		LmdbStore reopened = new LmdbStore(directory.toFile(), settings);
		try (AutoCloseable ignored = reopened::shutDown) {
			reopened.init();
			LmdbTestUtil.awaitPostReadyInitialization(reopened, 30, TimeUnit.SECONDS);
			assertPredicateValues(reopened.getBackingStore(), java.util.Set.of(O, literal, later));
			assertEquals(updated, pairedDomain(reopened.getBackingStore(), predicateId).orElseThrow());
		}
	}

